-- Additive LeaveDesk history is retained through account removal and application rollback.
begin;
create table if not exists public.leave_types(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 1 and 100),enabled boolean not null default true);
insert into public.leave_types(id,name) values('f1000000-0000-4000-8000-000000000001','Annual / earned'),('f1000000-0000-4000-8000-000000000002','Casual / personal'),('f1000000-0000-4000-8000-000000000003','Sick / medical'),('f1000000-0000-4000-8000-000000000004','Unpaid'),('f1000000-0000-4000-8000-000000000005','Compensatory off'),('f1000000-0000-4000-8000-000000000006','Optional / restricted holiday') on conflict(id) do nothing;
create table if not exists public.leave_policies(id uuid primary key default gen_random_uuid(),name text not null,year_start integer not null check(year_start in(1,4)),allowances jsonb not null default '[]');
create table if not exists public.leave_calendars(id uuid primary key default gen_random_uuid(),name text not null,timezone text not null,weekdays integer[] not null check(cardinality(weekdays)>0 and weekdays <@ array[1,2,3,4,5,6,7]));
create table if not exists public.leave_assignments(user_id uuid primary key references public.profiles,policy_id uuid not null references public.leave_policies,calendar_id uuid not null references public.leave_calendars,reason text not null,created_at timestamptz not null default now());
create table if not exists public.leave_holidays(id uuid primary key default gen_random_uuid(),calendar_id uuid references public.leave_calendars,date date not null,name text not null,kind text not null check(kind in('company','india_central','india_regional','india_restricted','us_federal')),source text not null,review_status text not null,check(kind<>'company' or calendar_id is not null));
create table if not exists public.leave_department_settings(department_id uuid primary key references public.employee_departments,minimum_available integer not null check(minimum_available>=0));
create table if not exists public.leave_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles,type_id uuid not null references public.leave_types,start_date date not null,end_date date not null,half text not null check(half in('full','first','second')),reason text not null default '',past_explanation text not null default '',handover text not null default '',backup_id uuid references public.profiles,status text not null default 'pending' check(status in('pending','changes_requested','approved','declined','withdrawn','cancel_pending','cancelled')),revision integer not null default 1,takeover_id uuid references public.profiles,policy_snapshot jsonb not null,calendar_snapshot jsonb not null,submitted_at timestamptz not null default now(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_date>=start_date));
create table if not exists public.leave_days(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.leave_requests,date date not null,half text not null,days numeric not null check(days in(0.5,1)),period_start date not null,tracked boolean not null,paid boolean not null,unique(request_id,date));
create index if not exists leave_days_date on public.leave_days(date);
create table if not exists public.leave_ledger(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles,type_id uuid not null references public.leave_types,period_start date not null,kind text not null check(kind in('opening','allowance','adjustment','reservation','release','booking','restore')),amount numeric not null,request_id uuid references public.leave_requests,actor_id uuid not null references public.profiles,reason text not null,created_at timestamptz not null default now());
create unique index if not exists leave_one_opening on public.leave_ledger(user_id,type_id,period_start) where kind in('opening','allowance');
create table if not exists public.leave_comments(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.leave_requests,actor_id uuid not null references public.profiles,body text not null,created_at timestamptz not null default now());
create table if not exists public.leave_history(id uuid primary key default gen_random_uuid(),request_id uuid references public.leave_requests,actor_id uuid not null references public.profiles,action text not null,payload jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists public.leave_files(id uuid primary key,request_id uuid not null references public.leave_requests,name text not null,path text not null unique,mime text not null check(mime in('application/pdf','image/jpeg','image/png')),size bigint not null check(size>0 and size<=10485760),created_at timestamptz not null default now());
create table if not exists public.leave_incident_records(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles,date date not null,expected_period text not null,comments text not null,explanation text,status text not null default 'recorded' check(status in('recorded','confirmed','dismissed','converted')),request_id uuid references public.leave_requests,revision integer not null default 1,created_at timestamptz not null default now());
create table if not exists public.leave_incident_history(id uuid primary key default gen_random_uuid(),incident_id uuid not null references public.leave_incident_records,actor_id uuid not null references public.profiles,action text not null,payload jsonb not null,created_at timestamptz not null default now());
create table if not exists public.leave_notifications(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.leave_requests,recipient_id uuid not null references public.profiles,actor_id uuid not null references public.profiles,type text not null,title text not null,body text not null,read_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.leave_operations(key uuid primary key,actor_id uuid not null references public.profiles,signature jsonb not null,result jsonb not null);
create or replace function public.leave_admin() returns boolean language sql stable security definer set search_path=public,pg_temp as $$select public.account_is_active() and exists(select from employee_admin_members where user_id=auth.uid())$$;
create or replace function public.leave_active(p_user uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select from account_private.accounts where id=p_user and status='active')$$;
create or replace function public.leave_manager(p_user uuid) returns uuid language sql stable security definer set search_path=public,pg_temp as $$select manager_id from employee_records where user_id=p_user and manager_id<>p_user and public.leave_active(manager_id)$$;
create or replace function public.leave_private(p_user uuid,p_takeover uuid default null) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select coalesce(public.account_is_active() and (auth.uid()=p_user or public.leave_admin() or (p_takeover is null and auth.uid()=public.leave_manager(p_user))),false)$$;
create or replace function public.leave_can_read(p_request uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select coalesce((select public.leave_private(user_id,takeover_id) from leave_requests where id=p_request),false)$$;
create or replace function public.leave_lock() returns void language plpgsql security definer set search_path=public,pg_temp as $$begin update employee_runtime set revision=revision+1 where singleton;if not public.account_is_active() then raise exception 'Account inactive' using errcode='42501';end if;end$$;
create or replace function public.leave_replay(p_key uuid,p_signature jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare o leave_operations;begin if p_key is null then raise exception 'Idempotency key required' using errcode='22023';end if;select * into o from leave_operations where key=p_key;if found then if o.actor_id<>auth.uid() or o.signature<>p_signature then raise exception 'Operation conflict' using errcode='23505';end if;return o.result;end if;return null;end$$;
create or replace function public.leave_save_operation(p_key uuid,p_signature jsonb,p_result jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin insert into leave_operations values(p_key,auth.uid(),p_signature,p_result);return p_result;end$$;
create or replace function public.leave_period(p_date date,p_start integer) returns date language sql immutable as $$select make_date(extract(year from p_date)::int-case when extract(month from p_date)<p_start then 1 else 0 end,p_start,1)$$;
create or replace function public.leave_scope(p_user uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select public.leave_private(p_user)$$;
-- None of these privileged helper functions are callable by clients except policy predicates.
revoke all on function public.leave_active(uuid),public.leave_manager(uuid),public.leave_lock(),public.leave_replay(uuid,jsonb),public.leave_save_operation(uuid,jsonb,jsonb),public.leave_period(date,integer) from public,anon,authenticated;

create or replace function public.leave_settings(p_kind text,p_payload jsonb,p_key uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare sig jsonb:=jsonb_build_array('settings',p_kind,p_payload);r jsonb;i uuid;v jsonb;u uuid;ps date;pol leave_policies;begin
 perform leave_lock();if not leave_admin() then raise exception 'Admin required' using errcode='42501';end if;r:=leave_replay(p_key,sig);if r is not null then return r;end if;i:=coalesce((p_payload->>'id')::uuid,gen_random_uuid());
 case p_kind
 when 'type' then insert into leave_types(id,name,enabled) values(i,trim(p_payload->>'name'),coalesce((p_payload->>'enabled')::boolean,true)) on conflict(id) do update set name=excluded.name,enabled=excluded.enabled returning to_jsonb(leave_types.*) into r;
 when 'policy' then
 if jsonb_typeof(p_payload->'allowances') is distinct from 'array' then raise exception 'Allowances required' using errcode='22023';end if;
 for v in select value from jsonb_array_elements(p_payload->'allowances') loop
 if not exists(select from leave_types where id=(v->>'type_id')::uuid) or v->>'days' is null or (v->>'days')::numeric not between 0 and 1000000 or (v->>'days')::numeric*2<>trunc((v->>'days')::numeric*2) or jsonb_typeof(v->'paid') is distinct from 'boolean' or jsonb_typeof(v->'tracked') is distinct from 'boolean' then raise exception 'Invalid allowance' using errcode='22023';end if;
 end loop;
 if (select count(*)<>count(distinct value->>'type_id') from jsonb_array_elements(p_payload->'allowances')) then raise exception 'Duplicate allowance type' using errcode='22023';end if;
 insert into leave_policies values(i,p_payload->>'name',(p_payload->>'year_start')::int,p_payload->'allowances') on conflict(id) do update set name=excluded.name,year_start=excluded.year_start,allowances=excluded.allowances returning to_jsonb(leave_policies.*) into r;
 when 'calendar' then
 if not exists(select from pg_timezone_names where name=p_payload->>'timezone') then raise exception 'Invalid timezone' using errcode='22023';end if;
 insert into leave_calendars values(i,p_payload->>'name',p_payload->>'timezone',array(select value::int from jsonb_array_elements_text(p_payload->'weekdays'))) on conflict(id) do update set name=excluded.name,timezone=excluded.timezone,weekdays=excluded.weekdays returning to_jsonb(leave_calendars.*) into r;
 when 'assignment' then
 u:=(p_payload->>'user_id')::uuid;if not leave_active(u) or not exists(select from employee_records where user_id=u) then raise exception 'Active employee required' using errcode='22023';end if;
 if length(trim(coalesce(p_payload->>'reason','')))=0 then raise exception 'Opening balance reason required' using errcode='22023';end if;
 select * into strict pol from leave_policies where id=(p_payload->>'policy_id')::uuid;
 if not exists(select from leave_assignments where user_id=u) and exists(select from jsonb_array_elements(pol.allowances) a where (a->>'tracked')::boolean) and jsonb_array_length(coalesce(p_payload->'opening_balances','[]'))=0 then raise exception 'Admin-confirmed opening balances required' using errcode='22023';end if;
 insert into leave_assignments(user_id,policy_id,calendar_id,reason) values(u,pol.id,(p_payload->>'calendar_id')::uuid,p_payload->>'reason') on conflict(user_id) do update set policy_id=excluded.policy_id,calendar_id=excluded.calendar_id,reason=excluded.reason returning to_jsonb(leave_assignments.*) into r;
 for v in select value from jsonb_array_elements(coalesce(p_payload->'opening_balances','[]')) loop
 ps:=(v->>'period_start')::date;if ps<>leave_period(ps,pol.year_start) or v->>'days' is null or (v->>'days')::numeric not between 0 and 1000000 or (v->>'days')::numeric*2<>trunc((v->>'days')::numeric*2) or not exists(select from jsonb_array_elements(pol.allowances) a where a->>'type_id'=v->>'type_id') then raise exception 'Invalid opening balance period or type' using errcode='22023';end if;
 insert into leave_ledger(user_id,type_id,period_start,kind,amount,actor_id,reason) values(u,(v->>'type_id')::uuid,ps,'opening',(v->>'days')::numeric,auth.uid(),p_payload->>'reason');end loop;
 when 'adjustment' then
 u:=(p_payload->>'user_id')::uuid;ps:=(p_payload->>'period_start')::date;
 if length(trim(coalesce(p_payload->>'reason','')))=0 or (p_payload->>'days') is null or (p_payload->>'days')::numeric=0 or abs((p_payload->>'days')::numeric)>1000000 or (p_payload->>'days')::numeric*2<>trunc((p_payload->>'days')::numeric*2) then raise exception 'Adjustment reason and days required' using errcode='22023';end if;
 if not exists(select from leave_ledger where user_id=u and type_id=(p_payload->>'type_id')::uuid and period_start=ps and kind in('opening','allowance')) then raise exception 'Opening balance required for period' using errcode='22023';end if;
 if coalesce((select sum(amount) from leave_ledger where user_id=u and type_id=(p_payload->>'type_id')::uuid and period_start=ps),0)+(p_payload->>'days')::numeric<0 then raise exception 'Insufficient balance for adjustment' using errcode='22023';end if;
 insert into leave_ledger(user_id,type_id,period_start,kind,amount,actor_id,reason) values(u,(p_payload->>'type_id')::uuid,ps,'adjustment',(p_payload->>'days')::numeric,auth.uid(),p_payload->>'reason') returning to_jsonb(leave_ledger.*) into r;
 when 'holiday' then insert into leave_holidays values(i,(p_payload->>'calendar_id')::uuid,(p_payload->>'date')::date,p_payload->>'name',p_payload->>'kind',p_payload->>'source',p_payload->>'review_status') on conflict(id) do update set calendar_id=excluded.calendar_id,date=excluded.date,name=excluded.name,kind=excluded.kind,source=excluded.source,review_status=excluded.review_status returning to_jsonb(leave_holidays.*) into r;
 when 'department' then insert into leave_department_settings values((p_payload->>'department_id')::uuid,(p_payload->>'minimum_available')::int) on conflict(department_id) do update set minimum_available=excluded.minimum_available returning to_jsonb(leave_department_settings.*) into r;
 else raise exception 'Unknown setting kind' using errcode='22023';end case;
 insert into leave_history(actor_id,action,payload) values(auth.uid(),'setting_'||p_kind,jsonb_build_object('saved',r,'reason',p_payload->>'reason'));
 return leave_save_operation(p_key,sig,r);end$$;

-- Snapshot allocation owns overlap checks and period reservations; caller holds runtime lock.
create or replace function public.leave_allocate(p_request uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare r leave_requests;v jsonb;d date;ps date;n numeric;total numeric;tracked boolean;paid boolean;begin
 select * into strict r from leave_requests where id=p_request;
 select a into v from jsonb_array_elements(r.policy_snapshot->'allowances') a where a->>'type_id'=r.type_id::text;
 if v is null then raise exception 'Leave type not assigned in policy' using errcode='22023';end if;tracked:=(v->>'tracked')::boolean;paid:=(v->>'paid')::boolean;
 if r.end_date-r.start_date>366 or (r.half<>'full' and r.start_date<>r.end_date) then raise exception 'Invalid request duration' using errcode='22023';end if;
 for d in select generate_series(r.start_date,r.end_date,'1 day')::date loop
 if extract(isodow from d)::int=any(array(select value::int from jsonb_array_elements_text(r.calendar_snapshot->'weekdays'))) and not exists(select from jsonb_array_elements(r.calendar_snapshot->'holidays') h where (h->>'date')::date=d) then
 if exists(select from leave_days ld join leave_requests lr on lr.id=ld.request_id where lr.user_id=r.user_id and lr.id<>r.id and lr.status in('pending','approved','cancel_pending') and ld.date=d and (ld.half='full' or r.half='full' or ld.half=r.half)) then raise exception 'Overlapping active request' using errcode='23505';end if;
 ps:=leave_period(d,(r.policy_snapshot->>'year_start')::int);n:=case when r.half='full' then 1 else 0.5 end;
 insert into leave_days(request_id,date,half,days,period_start,tracked,paid) values(r.id,d,r.half,n,ps,tracked,paid);
 end if;end loop;
 if not exists(select from leave_days where request_id=r.id) then raise exception 'No scheduled working days' using errcode='22023';end if;
 if tracked then for ps,total in select period_start,sum(days) from leave_days where request_id=r.id group by period_start loop
 -- Opening periods are confirmed explicitly. Later periods receive only the configured fixed allowance.
 if not exists(select from leave_ledger where user_id=r.user_id and type_id=r.type_id and period_start=ps and kind in('opening','allowance')) then
 if exists(select from leave_ledger where user_id=r.user_id and type_id=r.type_id and kind='opening' and period_start<ps) then
 insert into leave_ledger(user_id,type_id,period_start,kind,amount,actor_id,reason) values(r.user_id,r.type_id,ps,'allowance',(v->>'days')::numeric,auth.uid(),'Configured fixed allowance for later period');
 else raise exception 'Confirmed opening balance required for allowance period' using errcode='22023';end if;end if;
 if coalesce((select sum(amount) from leave_ledger where user_id=r.user_id and type_id=r.type_id and period_start=ps),0)<total then raise exception 'Insufficient balance' using errcode='22023';end if;
 insert into leave_ledger(user_id,type_id,period_start,kind,amount,request_id,actor_id,reason) values(r.user_id,r.type_id,ps,'reservation',-total,r.id,auth.uid(),'Submitted reservation');end loop;end if;
end$$;
create or replace function public.leave_notify(p_request uuid,p_action text) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare r leave_requests;recipient uuid;begin select * into strict r from leave_requests where id=p_request;
 for recipient in select distinct x from unnest(array[r.user_id,coalesce(r.takeover_id,leave_manager(r.user_id))]) x where x is not null and x<>auth.uid() and leave_active(x) loop
 insert into leave_notifications(request_id,recipient_id,actor_id,type,title,body) values(r.id,recipient,auth.uid(),p_action,'Leave request update','A leave request needs your attention.');end loop;
 if leave_manager(r.user_id) is null and r.takeover_id is null then insert into leave_notifications(request_id,recipient_id,actor_id,type,title,body) select r.id,user_id,auth.uid(),p_action,'Leave review required','A leave request requires independent review.' from employee_admin_members where user_id<>r.user_id and user_id<>auth.uid() and leave_active(user_id);end if;end$$;
create or replace function public.leave_submit(p_payload jsonb,p_key uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare sig jsonb:=jsonb_build_array('submit',p_payload);result jsonb;r leave_requests;a leave_assignments;p leave_policies;c leave_calendars;s date;e date;begin
 perform leave_lock();result:=leave_replay(p_key,sig);if result is not null then return result;end if;
 select * into a from leave_assignments where user_id=auth.uid();if not found then raise exception 'Policy/calendar assignment required' using errcode='22023';end if;select * into strict p from leave_policies where id=a.policy_id;select * into strict c from leave_calendars where id=a.calendar_id;
 s:=(p_payload->>'start_date')::date;e:=(p_payload->>'end_date')::date;
 if s<(clock_timestamp() at time zone c.timezone)::date and length(trim(coalesce(p_payload->>'past_explanation','')))=0 then raise exception 'Past-date explanation required' using errcode='22023';end if;
 if not exists(select from leave_types where id=(p_payload->>'type_id')::uuid and enabled) then raise exception 'Enabled leave type required' using errcode='22023';end if;
 if p_payload->>'backup_id' is not null and (not leave_active((p_payload->>'backup_id')::uuid) or (p_payload->>'backup_id')::uuid=auth.uid()) then raise exception 'Choose another active backup colleague' using errcode='22023';end if;
 insert into leave_requests(user_id,type_id,start_date,end_date,half,reason,past_explanation,handover,backup_id,policy_snapshot,calendar_snapshot) values(auth.uid(),(p_payload->>'type_id')::uuid,s,e,coalesce(p_payload->>'half','full'),coalesce(p_payload->>'reason',''),coalesce(p_payload->>'past_explanation',''),coalesce(p_payload->>'handover',''),(p_payload->>'backup_id')::uuid,to_jsonb(p),to_jsonb(c)||jsonb_build_object('holidays',coalesce((select jsonb_agg(to_jsonb(h)) from leave_holidays h where h.calendar_id=c.id and h.kind='company' and h.date between s and e),'[]'))) returning * into r;
 perform leave_allocate(r.id);insert into leave_history(request_id,actor_id,action,payload) values(r.id,auth.uid(),'submitted',to_jsonb(r));perform leave_notify(r.id,'submitted');return leave_save_operation(p_key,sig,to_jsonb(r));end$$;
create or replace function public.leave_action(p_request uuid,p_revision integer,p_action text,p_payload jsonb,p_key uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare r leave_requests;sig jsonb:=jsonb_build_array('action',p_request,p_revision,p_action,p_payload);result jsonb;reviewer boolean;ps date;total numeric;reason text:=trim(coalesce(p_payload->>'reason',''));a leave_assignments;c leave_calendars;p leave_policies;begin
 perform leave_lock();select * into r from leave_requests where id=p_request;if not found or not leave_can_read(p_request) then raise exception 'Request access denied' using errcode='42501';end if;
 result:=leave_replay(p_key,sig);if result is not null then return result;end if;if p_revision is distinct from r.revision then raise exception 'Stale request revision' using errcode='40001';end if;
 reviewer:=auth.uid()<>r.user_id and ((r.takeover_id is not null and r.takeover_id=auth.uid() and leave_admin()) or (r.takeover_id is null and auth.uid()=leave_manager(r.user_id)) or (r.takeover_id is null and leave_manager(r.user_id) is null and leave_admin()));
 if p_action in('approve','decline','changes','accept_cancel','reject_cancel') and reviewer is not true then raise exception 'Independent reviewer required; admin takeover required for an eligible manager' using errcode='42501';end if;
 if p_action in('decline','changes','takeover','comment','reject_cancel') and reason='' then raise exception 'Reason required' using errcode='22023';end if;
 case p_action
 when 'takeover' then if not leave_admin() or auth.uid()=r.user_id or r.status not in('pending','cancel_pending') then raise exception 'Independent admin takeover required' using errcode='42501';end if;update leave_requests set takeover_id=auth.uid() where id=r.id;
 when 'comment' then insert into leave_comments(request_id,actor_id,body) values(r.id,auth.uid(),reason);
 when 'approve' then if r.status<>'pending' then raise exception 'Pending request required' using errcode='22023';end if;update leave_requests set status='approved' where id=r.id;
 insert into leave_ledger(user_id,type_id,period_start,kind,amount,request_id,actor_id,reason) select r.user_id,r.type_id,period_start,'release',sum(days),r.id,auth.uid(),'Reservation converted' from leave_days where request_id=r.id and tracked group by period_start;
 insert into leave_ledger(user_id,type_id,period_start,kind,amount,request_id,actor_id,reason) select r.user_id,r.type_id,period_start,'booking',-sum(days),r.id,auth.uid(),'Approved booking' from leave_days where request_id=r.id and tracked group by period_start;
 when 'decline','changes','withdraw' then
 if (r.status<>'pending' and not(p_action='withdraw' and r.status='changes_requested')) or (p_action='withdraw' and auth.uid()<>r.user_id) then raise exception 'Pending requester/reviewer action required' using errcode='42501';end if;
 update leave_requests set status=case p_action when 'decline' then 'declined' when 'changes' then 'changes_requested' else 'withdrawn' end where id=r.id;
 insert into leave_ledger(user_id,type_id,period_start,kind,amount,request_id,actor_id,reason) select r.user_id,r.type_id,period_start,'release',sum(days),r.id,auth.uid(),coalesce(nullif(reason,''),'Withdrawn reservation') from leave_days where request_id=r.id and tracked and r.status='pending' group by period_start;
 when 'resubmit' then
 if auth.uid()<>r.user_id or r.status<>'changes_requested' then raise exception 'Requester changes required' using errcode='42501';end if;
 select * into strict a from leave_assignments where user_id=r.user_id;select * into strict p from leave_policies where id=a.policy_id;select * into strict c from leave_calendars where id=a.calendar_id;
 update leave_requests set type_id=coalesce((p_payload->>'type_id')::uuid,type_id),start_date=coalesce((p_payload->>'start_date')::date,start_date),end_date=coalesce((p_payload->>'end_date')::date,end_date),half=coalesce(p_payload->>'half',half),reason=coalesce(p_payload->>'reason',leave_requests.reason),past_explanation=coalesce(p_payload->>'past_explanation',past_explanation),handover=coalesce(p_payload->>'handover',handover),backup_id=case when p_payload?'backup_id' then (p_payload->>'backup_id')::uuid else backup_id end,policy_snapshot=to_jsonb(p),calendar_snapshot=to_jsonb(c),takeover_id=null,status='pending',submitted_at=clock_timestamp() where id=r.id returning * into r;
 if not exists(select from leave_types where id=r.type_id and enabled) then raise exception 'Enabled type required' using errcode='22023';end if;
 if r.start_date<(clock_timestamp() at time zone c.timezone)::date and length(trim(r.past_explanation))=0 then raise exception 'Past-date explanation required' using errcode='22023';end if;
 if r.backup_id is not null and (r.backup_id=r.user_id or not leave_active(r.backup_id)) then raise exception 'Active independent backup required' using errcode='22023';end if;
 update leave_requests set calendar_snapshot=calendar_snapshot||jsonb_build_object('holidays',coalesce((select jsonb_agg(to_jsonb(h)) from leave_holidays h where h.calendar_id=c.id and h.kind='company' and h.date between r.start_date and r.end_date),'[]')) where id=r.id;
 delete from leave_days where request_id=r.id;perform leave_allocate(r.id);
 when 'cancel' then if auth.uid()<>r.user_id or r.status<>'approved' then raise exception 'Approved requester cancellation required' using errcode='42501';end if;update leave_requests set status='cancel_pending' where id=r.id;
 when 'accept_cancel' then if r.status<>'cancel_pending' then raise exception 'Pending cancellation required' using errcode='22023';end if;update leave_requests set status='cancelled' where id=r.id;
 insert into leave_ledger(user_id,type_id,period_start,kind,amount,request_id,actor_id,reason) select r.user_id,r.type_id,period_start,'restore',sum(days),r.id,auth.uid(),'Cancellation accepted' from leave_days where request_id=r.id and tracked group by period_start;
 when 'reject_cancel' then if r.status<>'cancel_pending' then raise exception 'Pending cancellation required' using errcode='22023';end if;update leave_requests set status='approved' where id=r.id;
 else raise exception 'Unknown leave action' using errcode='22023';end case;
 update leave_requests set revision=revision+1,updated_at=clock_timestamp() where id=r.id returning * into r;
 insert into leave_history(request_id,actor_id,action,payload) values(r.id,auth.uid(),p_action,p_payload||jsonb_build_object('revision',r.revision));perform leave_notify(r.id,p_action);return leave_save_operation(p_key,sig,to_jsonb(r));end$$;

create or replace function public.leave_request_json(p_request uuid) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$select to_jsonb(r)||jsonb_build_object('total_days',coalesce((select sum(days) from leave_days where request_id=r.id),0),'reviewer_id',coalesce(r.takeover_id,leave_manager(r.user_id)),'can_review',coalesce(auth.uid()<>r.user_id and ((r.takeover_id=auth.uid() and leave_admin()) or (r.takeover_id is null and (auth.uid()=leave_manager(r.user_id) or (leave_manager(r.user_id) is null and leave_admin())))),false)) from leave_requests r where id=p_request$$;
create or replace function public.leave_detail(p_request uuid) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$begin
 if not leave_can_read(p_request) then raise exception 'Request access denied' using errcode='42501';end if;
 return jsonb_build_object('request',leave_request_json(p_request),'task_warnings',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'title',c.title,'board_id',c.board_id,'due_date',c.due_date)) from cards c join leave_requests r on r.id=p_request where c.assignee_id=r.user_id and public.user_has_board_access(c.board_id) and exists(select from leave_days d where d.request_id=r.id and d.date=(c.due_date at time zone (r.calendar_snapshot->>'timezone'))::date)),'[]'),'days',coalesce((select jsonb_agg(to_jsonb(d) order by d.date) from leave_days d where request_id=p_request),'[]'),'comments',coalesce((select jsonb_agg(to_jsonb(c) order by c.created_at) from leave_comments c where request_id=p_request),'[]'),'files',coalesce((select jsonb_agg(to_jsonb(f)) from leave_files f where request_id=p_request),'[]'),'history',coalesce((select jsonb_agg(to_jsonb(h) order by h.created_at) from leave_history h where request_id=p_request),'[]'));end$$;
create or replace function public.leave_list(p_view text) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$begin if not account_is_active() then raise exception 'Account inactive' using errcode='42501';end if;if p_view not in('mine','approvals') then raise exception 'Unknown view' using errcode='22023';end if;
 return coalesce((select jsonb_agg(leave_request_json(r.id) order by r.created_at desc) from leave_requests r where leave_can_read(r.id) and ((p_view='mine' and r.user_id=auth.uid()) or (p_view='approvals' and r.user_id<>auth.uid()))),'[]');end$$;
create or replace function public.leave_context() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare a leave_assignments;begin if not account_is_active() then raise exception 'Account inactive' using errcode='42501';end if;select * into a from leave_assignments where user_id=auth.uid();return jsonb_build_object('userId',auth.uid(),'admin',leave_admin(),'manager',exists(select from employee_records where manager_id=auth.uid()),'employees',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',coalesce(p.full_name,p.email),'department_id',e.department_id)) from profiles p join employee_records e on e.user_id=p.id where leave_active(p.id)),'[]'),'departments',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'name',d.name,'minimum_available',s.minimum_available)) from employee_departments d left join leave_department_settings s on s.department_id=d.id where not d.archived),'[]'),'types',coalesce((select jsonb_agg(to_jsonb(t)) from leave_types t where leave_admin() or t.enabled),'[]'),'policies',coalesce((select jsonb_agg(to_jsonb(p)) from leave_policies p where leave_admin() or p.id=a.policy_id),'[]'),'calendars',coalesce((select jsonb_agg(to_jsonb(c)) from leave_calendars c where leave_admin() or c.id=a.calendar_id),'[]'),'holidays',case when leave_admin() then coalesce((select jsonb_agg(to_jsonb(h) order by h.date) from leave_holidays h),'[]') else '[]'::jsonb end,'assignments',case when leave_admin() then coalesce((select jsonb_agg(to_jsonb(x)) from leave_assignments x),'[]') else '[]'::jsonb end,'assignment',case when a.user_id is not null then to_jsonb(a) else null end);end$$;
create or replace function public.leave_balances(p_user uuid default null) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare u uuid:=coalesce(p_user,auth.uid());tz text;today date;begin if not leave_scope(u) then raise exception 'Balance access denied' using errcode='42501';end if;select c.timezone into tz from leave_assignments a join leave_calendars c on c.id=a.calendar_id where user_id=u;today:=(now() at time zone coalesce(tz,'UTC'))::date;
 return coalesce((select jsonb_agg(jsonb_build_object('type_id',b.type_id,'type_name',t.name,'tracked',coalesce((select bool_or(d.tracked) from leave_days d join leave_requests r on r.id=d.request_id where r.user_id=u and r.type_id=b.type_id and d.period_start=b.period_start),true),'period_start',b.period_start,'allowance',b.allowance,'adjustments',b.adjustments,'remaining',b.remaining,'used',coalesce((select sum(d.days) from leave_days d join leave_requests r on r.id=d.request_id where r.user_id=u and r.type_id=b.type_id and d.period_start=b.period_start and r.status in('approved','cancel_pending') and d.date<(now() at time zone (r.calendar_snapshot->>'timezone'))::date),0),'booked',coalesce((select sum(d.days) from leave_days d join leave_requests r on r.id=d.request_id where r.user_id=u and r.type_id=b.type_id and d.period_start=b.period_start and r.status in('approved','cancel_pending') and d.date>=(now() at time zone (r.calendar_snapshot->>'timezone'))::date),0),'pending',coalesce((select sum(d.days) from leave_days d join leave_requests r on r.id=d.request_id where r.user_id=u and r.type_id=b.type_id and d.period_start=b.period_start and r.status='pending'),0))) from (select type_id,period_start,sum(amount) remaining,coalesce(sum(amount) filter(where kind in('opening','allowance')),0) allowance,coalesce(sum(amount) filter(where kind='adjustment'),0) adjustments from (select type_id,period_start,kind,amount from leave_ledger where user_id=u union all select distinct r.type_id,d.period_start,null::text,0::numeric from leave_days d join leave_requests r on r.id=d.request_id where r.user_id=u and not d.tracked union all select (v->>'type_id')::uuid,leave_period(today,p.year_start),'allowance',(v->>'days')::numeric from leave_assignments a join leave_policies p on p.id=a.policy_id cross join lateral jsonb_array_elements(p.allowances) v where a.user_id=u and (v->>'tracked')::boolean and exists(select from leave_ledger l where l.user_id=u and l.type_id=(v->>'type_id')::uuid and l.kind='opening' and l.period_start<leave_period(today,p.year_start)) and not exists(select from leave_ledger l where l.user_id=u and l.type_id=(v->>'type_id')::uuid and l.period_start=leave_period(today,p.year_start) and l.kind in('opening','allowance'))) amounts group by type_id,period_start) b join leave_types t on t.id=b.type_id),'[]');end$$;
create or replace function public.leave_calendar(p_start date,p_end date,p_department uuid default null) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare dept uuid;cal uuid;events jsonb;holidays jsonb;warnings jsonb;begin
 if not account_is_active() then raise exception 'Account inactive' using errcode='42501';end if;if p_start is null or p_end is null or p_end<p_start or p_end-p_start>92 then raise exception 'Calendar range must be 1 to 93 days' using errcode='22023';end if;
 select department_id into dept from employee_records where user_id=auth.uid();select calendar_id into cal from leave_assignments where user_id=auth.uid();
 if p_department is not null and p_department is distinct from dept and not leave_admin() and not exists(select from employee_records where manager_id=auth.uid() and department_id=p_department) then raise exception 'Department access denied' using errcode='42501';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'user_id',r.user_id,'name',coalesce(p.full_name,p.email),'start_date',r.start_date,'end_date',r.end_date,'status',case when r.status='cancel_pending' then 'approved' else r.status end,'label','On leave')),'[]') into events from leave_requests r join profiles p on p.id=r.user_id left join employee_records e on e.user_id=r.user_id where r.end_date>=p_start and r.start_date<=p_end and ((p_department is null and r.user_id=auth.uid()) or (p_department=e.department_id)) and (r.status in('approved','cancel_pending') or (r.status='pending' and leave_can_read(r.id)));
 select coalesce(jsonb_agg(jsonb_build_object('date',date,'name',name,'kind',kind,'source',source,'review_status',review_status)),'[]') into holidays from leave_holidays where date between p_start and p_end and (calendar_id is null or calendar_id=cal);
 -- Availability warnings use each employee's assigned calendar; they never reject leave.
 select coalesce(jsonb_agg(jsonb_build_object('date',x.date,'department_id',x.department_id,'available',x.available,'minimum_available',x.minimum_available)),'[]') into warnings from (
 select d::date date,s.department_id,s.minimum_available,count(e.user_id) filter(where extract(isodow from d)::int=any(c.weekdays) and not exists(select from leave_holidays h where h.calendar_id=c.id and h.kind='company' and h.date=d::date) and not exists(select from leave_days ld join leave_requests lr on lr.id=ld.request_id where lr.user_id=e.user_id and lr.status in('approved','cancel_pending') and ld.date=d::date)) available
 from generate_series(p_start,p_end,'1 day') d cross join leave_department_settings s join employee_records e on e.department_id=s.department_id join leave_assignments a on a.user_id=e.user_id join leave_calendars c on c.id=a.calendar_id where s.department_id=coalesce(p_department,dept) and leave_active(e.user_id) group by d,s.department_id,s.minimum_available having count(e.user_id) filter(where extract(isodow from d)::int=any(c.weekdays) and not exists(select from leave_holidays h where h.calendar_id=c.id and h.kind='company' and h.date=d::date) and not exists(select from leave_days ld join leave_requests lr on lr.id=ld.request_id where lr.user_id=e.user_id and lr.status in('approved','cancel_pending') and ld.date=d::date))<s.minimum_available) x;
 return jsonb_build_object('events',events,'holidays',holidays,'warnings',warnings);end$$;
create or replace function public.leave_insights() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$begin if not account_is_active() then raise exception 'Account inactive' using errcode='42501';end if;
 return jsonb_build_object('balances',leave_balances(),'people_away',coalesce((select jsonb_agg(to_jsonb(away)) from (select r.user_id,coalesce(p.full_name,p.email) name,min(r.start_date) start_date,max(r.end_date) end_date from leave_requests r join profiles p on p.id=r.user_id where leave_scope(r.user_id) and r.status in('approved','cancel_pending') and exists(select from leave_days d where d.request_id=r.id and d.date=(now() at time zone (r.calendar_snapshot->>'timezone'))::date) group by r.user_id,p.full_name,p.email) away),'[]'),'overlaps',coalesce((select jsonb_agg(to_jsonb(x)) from (select d.date,count(distinct r.user_id) people from leave_days d join leave_requests r on r.id=d.request_id where leave_scope(r.user_id) and r.status in('approved','cancel_pending') group by d.date having count(distinct r.user_id)>1) x),'[]'),'pending_count',(select count(*) from leave_requests where leave_scope(user_id) and status in('pending','cancel_pending')),'average_wait_days',coalesce((select avg(extract(epoch from (now()-submitted_at))/86400) from leave_requests where leave_scope(user_id) and status='pending'),0),'monthly',coalesce((select jsonb_agg(to_jsonb(x)) from (select to_char(d.date,'YYYY-MM') as "month",sum(d.days) days from leave_days d join leave_requests r on r.id=d.request_id where leave_scope(r.user_id) and r.status in('approved','cancel_pending') group by to_char(d.date,'YYYY-MM') order by 1) x),'[]'),'unresolved_ncns',(select count(*) from leave_incident_records where leave_scope(user_id) and status in('recorded','confirmed')));end$$;
create or replace function public.leave_incidents() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$begin if not account_is_active() then raise exception 'Account inactive' using errcode='42501';end if;return coalesce((select jsonb_agg(to_jsonb(i)||jsonb_build_object('history',coalesce((select jsonb_agg(to_jsonb(h) order by h.created_at) from leave_incident_history h where incident_id=i.id),'[]')) order by i.date desc) from leave_incident_records i where leave_scope(i.user_id)),'[]');end$$;
create or replace function public.leave_incident(p_payload jsonb,p_key uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare sig jsonb:=jsonb_build_array('incident',p_payload);r leave_incident_records;result jsonb;act text:=p_payload->>'action';reason text:=trim(coalesce(p_payload->>'reason',''));u uuid;begin
 perform leave_lock();if p_payload->>'id' is not null then select * into r from leave_incident_records where id=(p_payload->>'id')::uuid;if not found or not leave_scope(r.user_id) then raise exception 'Incident access denied' using errcode='42501';end if;u:=r.user_id;else u:=(p_payload->>'user_id')::uuid;end if;
 if act<>'explain' and (u=auth.uid() or (leave_admin() or leave_manager(u)=auth.uid()) is not true) then raise exception 'Independent manager/admin required' using errcode='42501';end if;
 if act='explain' and u is distinct from auth.uid() then raise exception 'Own explanation only' using errcode='42501';end if;
 result:=leave_replay(p_key,sig);if result is not null then return result;end if;
 if reason='' then raise exception 'Incident reason required' using errcode='22023';end if;
 if act<>'record' and ((p_payload->>'revision')::integer is distinct from r.revision) then raise exception 'Stale incident revision' using errcode='40001';end if;
 case act when 'record' then
 if r.id is not null or not leave_active(u) or not exists(select from employee_records where user_id=u) or length(trim(coalesce(p_payload->>'expected_period','')))=0 then raise exception 'Active employee and expected period required' using errcode='22023';end if;
 insert into leave_incident_records(user_id,date,expected_period,comments) values(u,(p_payload->>'date')::date,p_payload->>'expected_period',reason) returning * into r;
 when 'explain' then update leave_incident_records set explanation=reason,revision=revision+1 where id=r.id returning * into r;
 when 'confirm' then if r.status not in('recorded','confirmed') then raise exception 'Open incident required' using errcode='22023';end if;update leave_incident_records set status='confirmed',revision=revision+1 where id=r.id returning * into r;
 when 'correct' then if r.status='converted' then raise exception 'Converted incident is immutable' using errcode='22023';end if;update leave_incident_records set date=coalesce((p_payload->>'date')::date,date),expected_period=coalesce(p_payload->>'expected_period',expected_period),comments=reason,revision=revision+1 where id=r.id returning * into r;
 when 'dismiss' then if r.status='converted' then raise exception 'Converted incident is immutable' using errcode='22023';end if;update leave_incident_records set status='dismissed',revision=revision+1 where id=r.id returning * into r;
 when 'convert' then
 if r.status not in('recorded','confirmed') or not exists(select from leave_requests q join leave_days d on d.request_id=q.id where q.id=(p_payload->>'request_id')::uuid and q.user_id=u and q.status='approved' and d.date=r.date) then raise exception 'Approved leave covering incident required' using errcode='22023';end if;
 if exists(select from leave_incident_records where id<>r.id and request_id=(p_payload->>'request_id')::uuid and date=r.date and status='converted') then raise exception 'Incident already converted for date' using errcode='23505';end if;
 update leave_incident_records set status='converted',request_id=(p_payload->>'request_id')::uuid,revision=revision+1 where id=r.id returning * into r;
 else raise exception 'Unknown incident action' using errcode='22023';end case;
 insert into leave_incident_history(incident_id,actor_id,action,payload) values(r.id,auth.uid(),act,p_payload);return leave_save_operation(p_key,sig,to_jsonb(r));end$$;

alter table leave_files add column if not exists sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$');
create or replace function public.leave_register_file(p_request uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare f leave_files;r leave_requests;begin
 perform leave_lock();if not leave_can_read(p_request) then raise exception 'File access denied' using errcode='42501';end if;select * into strict r from leave_requests where id=p_request;
 if p_payload->>'path'<>p_request::text||'/'||(p_payload->>'id')::uuid::text or p_payload->>'path' is null or length(trim(coalesce(p_payload->>'name','')))=0 or length(p_payload->>'name')>255 then raise exception 'Invalid file path or name' using errcode='22023';end if;
 select * into f from leave_files where id=(p_payload->>'id')::uuid;
 if found then if f.request_id<>p_request or f.name<>p_payload->>'name' or f.path<>p_payload->>'path' or f.mime<>p_payload->>'mime' or f.size<>(p_payload->>'size')::bigint or f.sha256 is distinct from p_payload->>'sha256' then raise exception 'File operation conflict' using errcode='23505';end if;return to_jsonb(f);end if;
 if r.status not in('pending','changes_requested') then raise exception 'Files require pending request or requested changes' using errcode='22023';end if;
 if not exists(select from storage.objects where bucket_id='leave-files' and name=p_payload->>'path') then raise exception 'Upload missing' using errcode='22023';end if;
 insert into leave_files(id,request_id,name,path,mime,size,sha256) values((p_payload->>'id')::uuid,p_request,p_payload->>'name',p_payload->>'path',p_payload->>'mime',(p_payload->>'size')::bigint,p_payload->>'sha256') returning * into f;
 update leave_requests set revision=revision+1,updated_at=clock_timestamp() where id=p_request;
 insert into leave_history(request_id,actor_id,action,payload) values(p_request,auth.uid(),'file',jsonb_build_object('id',f.id,'name',f.name));return to_jsonb(f);end$$;
create or replace function public.leave_mark_notifications_read(p_id uuid default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare n integer;begin perform leave_lock();update leave_notifications set read_at=coalesce(read_at,clock_timestamp()) where recipient_id=auth.uid() and leave_can_read(request_id) and (p_id is null or id=p_id);get diagnostics n=row_count;return jsonb_build_object('count',n);end$$;

-- New tables do not inherit earlier account-lifecycle RLS policies: every predicate checks active status.
do $$declare t text;begin foreach t in array array['leave_types','leave_policies','leave_calendars','leave_assignments','leave_holidays','leave_department_settings','leave_requests','leave_days','leave_ledger','leave_comments','leave_history','leave_files','leave_incident_records','leave_incident_history','leave_notifications','leave_operations'] loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);
 end loop;end$$;
drop policy if exists leave_types_read on leave_types; create policy leave_types_read on leave_types for select to authenticated using(account_is_active());
drop policy if exists leave_policy_read on leave_policies; create policy leave_policy_read on leave_policies for select to authenticated using(account_is_active() and (leave_admin() or exists(select from leave_assignments where user_id=auth.uid() and policy_id=leave_policies.id)));
drop policy if exists leave_calendar_read on leave_calendars; create policy leave_calendar_read on leave_calendars for select to authenticated using(account_is_active() and (leave_admin() or exists(select from leave_assignments where user_id=auth.uid() and calendar_id=leave_calendars.id)));
drop policy if exists leave_assignment_read on leave_assignments; create policy leave_assignment_read on leave_assignments for select to authenticated using(leave_scope(user_id));
drop policy if exists leave_holiday_read on leave_holidays; create policy leave_holiday_read on leave_holidays for select to authenticated using(account_is_active() and (calendar_id is null or leave_admin() or exists(select from leave_assignments where user_id=auth.uid() and calendar_id=leave_holidays.calendar_id)));
drop policy if exists leave_department_read on leave_department_settings; create policy leave_department_read on leave_department_settings for select to authenticated using(account_is_active());
drop policy if exists leave_request_read on leave_requests; create policy leave_request_read on leave_requests for select to authenticated using(leave_private(user_id,takeover_id));
drop policy if exists leave_days_read on leave_days; create policy leave_days_read on leave_days for select to authenticated using(leave_can_read(request_id));
drop policy if exists leave_ledger_read on leave_ledger; create policy leave_ledger_read on leave_ledger for select to authenticated using(leave_scope(user_id));
drop policy if exists leave_comment_read on leave_comments; create policy leave_comment_read on leave_comments for select to authenticated using(leave_can_read(request_id));
drop policy if exists leave_history_read on leave_history; create policy leave_history_read on leave_history for select to authenticated using(case when request_id is null then leave_admin() else leave_can_read(request_id) end);
drop policy if exists leave_files_read on leave_files; create policy leave_files_read on leave_files for select to authenticated using(leave_can_read(request_id));
drop policy if exists leave_incidents_read on leave_incident_records; create policy leave_incidents_read on leave_incident_records for select to authenticated using(leave_scope(user_id));
drop policy if exists leave_incident_history_read on leave_incident_history; create policy leave_incident_history_read on leave_incident_history for select to authenticated using(exists(select from leave_incident_records i where i.id=incident_id and leave_scope(i.user_id)));
drop policy if exists leave_notification_read on leave_notifications; create policy leave_notification_read on leave_notifications for select to authenticated using(recipient_id=auth.uid() and leave_can_read(request_id));
-- Operation records have no direct policy: their result may contain private historical data.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('leave-files','leave-files',false,10485760,array['application/pdf','image/jpeg','image/png']) on conflict(id) do nothing;
-- No Storage SELECT permission: downloads must use fresh RLS metadata authorization then server transport.
-- Restrictive policy also blocks future broad storage policies from exposing these objects.
drop policy if exists leave_storage_private_read on storage.objects; create policy leave_storage_private_read on storage.objects as restrictive for select to authenticated using(bucket_id<>'leave-files');
drop policy if exists leave_storage_insert on storage.objects; create policy leave_storage_insert on storage.objects for insert to authenticated with check(bucket_id='leave-files' and array_length(string_to_array(name,'/'),1)=2 and leave_can_read((string_to_array(name,'/'))[1]::uuid) and (string_to_array(name,'/'))[2] ~ '^[a-fA-F0-9-]{36}$' and exists(select from leave_requests where id=(string_to_array(name,'/'))[1]::uuid and status in('pending','changes_requested')));
drop policy if exists leave_storage_no_update on storage.objects; create policy leave_storage_no_update on storage.objects as restrictive for update to authenticated using(bucket_id<>'leave-files') with check(bucket_id<>'leave-files');
drop policy if exists leave_storage_no_delete on storage.objects; create policy leave_storage_no_delete on storage.objects as restrictive for delete to authenticated using(bucket_id<>'leave-files');
-- Revoke the default PUBLIC function execution grant, exposing only the approved RPCs and RLS predicates.
do $$declare f record;begin for f in select oid::regprocedure sig from pg_proc where pronamespace='public'::regnamespace and proname like 'leave\_%' escape '\' loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);end loop;end$$;
grant execute on function public.leave_admin(),public.leave_private(uuid,uuid),public.leave_can_read(uuid),public.leave_scope(uuid),public.leave_context(),public.leave_list(text),public.leave_detail(uuid),public.leave_submit(jsonb,uuid),public.leave_action(uuid,integer,text,jsonb,uuid),public.leave_calendar(date,date,uuid),public.leave_balances(uuid),public.leave_insights(),public.leave_settings(text,jsonb,uuid),public.leave_incidents(),public.leave_incident(jsonb,uuid),public.leave_register_file(uuid,jsonb),public.leave_mark_notifications_read(uuid) to authenticated;
commit;
